-- Enable realtime delivery for new messages.
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'messages'
  ) then alter publication supabase_realtime add table public.messages; end if;
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'direct_messages'
  ) then alter publication supabase_realtime add table public.direct_messages; end if;
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'friendships'
  ) then alter publication supabase_realtime add table public.friendships; end if;
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'lobby_settings'
  ) then alter publication supabase_realtime add table public.lobby_settings; end if;
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'blocks'
  ) then alter publication supabase_realtime add table public.blocks; end if;
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'reports'
  ) then alter publication supabase_realtime add table public.reports; end if;
end $$;

-- ============================================================
-- COMMUNITY EXPANSION: public rooms, multi-tags, moderation,
-- bulletins, Top Friends, profile HTML, statuses and audit logs.
-- ============================================================

alter table public.profiles add column if not exists tags text[] not null default '{}';
update public.profiles set tags=array['OWNER'] where id=(select id from public.profiles where role='moderator' order by created_at limit 1) and not exists(select 1 from public.profiles where 'OWNER'=any(tags));
alter table public.profiles drop constraint if exists profiles_tags_check;
alter table public.profiles add constraint profiles_tags_check check (tags <@ array['OWNER','CO-OWNER','DEVELOPER','MOD']::text[] and cardinality(tags)<=4);
alter table public.profiles add column if not exists status_mode text not null default 'online';
alter table public.profiles add column if not exists away_message text not null default '';
alter table public.profiles add column if not exists profile_html text not null default '';
alter table public.profiles add column if not exists entry_sound boolean not null default false;
alter table public.profiles drop constraint if exists profiles_status_mode_check;
alter table public.profiles add constraint profiles_status_mode_check check (status_mode in ('online','away','busy','invisible'));
alter table public.profiles drop constraint if exists profiles_away_message_check;
alter table public.profiles add constraint profiles_away_message_check check (char_length(away_message) <= 120);
alter table public.profiles drop constraint if exists profiles_profile_html_check;
alter table public.profiles add constraint profiles_profile_html_check check (char_length(profile_html) <= 12000);
alter table public.profiles drop column if exists stickers;

alter table public.messages add column if not exists caption text not null default '';
alter table public.messages drop constraint if exists messages_caption_check;
alter table public.messages add constraint messages_caption_check check (char_length(caption) <= 300);
alter table public.messages drop constraint if exists messages_room_check;

create table if not exists public.rooms (
  slug text primary key check (slug ~ '^[a-z0-9_-]{2,32}$'),
  name text not null check (char_length(name) between 2 and 48),
  description text not null default '' check (char_length(description) <= 300),
  owner_id uuid references public.profiles(id) on delete set null,
  slow_mode_seconds integer not null default 0 check (slow_mode_seconds >= 0),
  media_mode text not null default 'allowed' check (media_mode in ('allowed','images_only','disabled')),
  minimum_role text not null default 'everyone' check (minimum_role in ('everyone','moderator','co_owner','owner')),
  is_builtin boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
insert into public.rooms(slug,name,description,is_builtin,media_mode) values
('lobby','Lobby','The main Symbiosis chat.',true,'allowed'),
('random','Random','Images and GIFs from across the Internet.',true,'images_only'),
('nostalgia','Nostalgia','Old-web images and GIFs.',true,'images_only')
on conflict (slug) do nothing;

create table if not exists public.bulletins (
  id bigint generated by default as identity primary key,
  author_id uuid not null references public.profiles(id) on delete cascade,
  title text not null check (char_length(trim(title)) between 1 and 100),
  body text not null check (char_length(trim(body)) between 1 and 2000),
  expires_at timestamptz,
  created_at timestamptz not null default now()
);

create table if not exists public.top_friends (
  user_id uuid not null references public.profiles(id) on delete cascade,
  friend_id uuid not null references public.profiles(id) on delete cascade,
  position smallint not null check (position between 1 and 8),
  primary key(user_id,friend_id), unique(user_id,position), check(user_id<>friend_id)
);

create table if not exists public.moderation_actions (
  id bigint generated by default as identity primary key,
  target_user_id uuid not null references public.profiles(id) on delete cascade,
  moderator_id uuid not null references public.profiles(id) on delete restrict,
  action_type text not null check (action_type in ('timeout','mute','kick','ban')),
  room_slug text references public.rooms(slug) on delete cascade,
  reason text not null default '' check (char_length(reason)<=500),
  expires_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz not null default now()
);

create table if not exists public.message_deletion_logs (
  id bigint generated by default as identity primary key,
  message_id bigint not null,
  author_id uuid,
  deleted_by uuid,
  room text not null,
  body text not null,
  caption text not null default '',
  created_at timestamptz not null,
  deleted_at timestamptz not null default now()
);

create or replace function public.has_staff_access(check_user uuid default auth.uid(), required text default 'moderator')
returns boolean language sql stable security definer set search_path=public as $$
  select exists(select 1 from profiles p where p.id=check_user and (
    'OWNER'=any(p.tags) or
    (required<>'owner' and 'CO-OWNER'=any(p.tags)) or
    (required='moderator' and ('MOD'=any(p.tags) or p.role='moderator'))
  ));
$$;
grant execute on function public.has_staff_access(uuid,text) to authenticated;

create or replace function public.is_moderator(check_user uuid default auth.uid())
returns boolean language sql stable security definer set search_path=public as $$
  select public.has_staff_access(check_user,'moderator');
$$;

create or replace function public.protect_profile_role()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if (new.role is distinct from old.role or new.tags is distinct from old.tags)
     and not public.has_staff_access(auth.uid(),'owner') then
    raise exception 'Only an owner can change account tags or staff access';
  end if;
  return new;
end;$$;

create or replace function public.enforce_message_access()
returns trigger language plpgsql security definer set search_path=public as $$
declare r rooms%rowtype; last_at timestamptz;
begin
  select * into r from rooms where slug=new.room;
  if not found then raise exception 'Room does not exist'; end if;
  if r.minimum_role<>'everyone' and not public.has_staff_access(new.user_id,r.minimum_role) then raise exception 'This room is locked to %+',r.minimum_role; end if;
  if exists(select 1 from moderation_actions a where a.target_user_id=new.user_id and a.revoked_at is null and (a.expires_at is null or a.expires_at>now()) and a.action_type in ('timeout','mute','kick','ban') and (a.room_slug is null or a.room_slug=new.room)) then raise exception 'You cannot post while a moderation action is active'; end if;
  if r.media_mode='images_only' and new.body !~* '^https?://[^[:space:]]+$' then raise exception '#% accepts image/GIF links only',new.room; end if;
  if r.media_mode='disabled' and new.body ~* '^https?://[^[:space:]]+$' then raise exception 'Media is disabled in this room'; end if;
  if not public.has_staff_access(new.user_id,'moderator') and r.slow_mode_seconds>0 then
    select max(created_at) into last_at from messages where user_id=new.user_id and room=new.room;
    if last_at is not null and now()<last_at+make_interval(secs=>r.slow_mode_seconds) then raise exception 'Slow mode: wait % seconds',ceil(extract(epoch from(last_at+make_interval(secs=>r.slow_mode_seconds)-now()))); end if;
  end if;
  return new;
end;$$;
drop trigger if exists enforce_lobby_slow_mode_trigger on public.messages;
drop trigger if exists enforce_media_only_rooms_trigger on public.messages;
drop trigger if exists enforce_message_access_trigger on public.messages;
create trigger enforce_message_access_trigger before insert on public.messages for each row execute function public.enforce_message_access();

create or replace function public.protect_room_staff_fields()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if not public.is_moderator(auth.uid()) and (new.owner_id is distinct from old.owner_id or new.minimum_role is distinct from old.minimum_role or new.is_builtin is distinct from old.is_builtin) then raise exception 'Only staff can change room ownership or access locks'; end if;
  return new;
end;$$;
drop trigger if exists protect_room_staff_fields_trigger on public.rooms;
create trigger protect_room_staff_fields_trigger before update on public.rooms for each row execute function public.protect_room_staff_fields();

create or replace function public.log_deleted_message()
returns trigger language plpgsql security definer set search_path=public as $$
begin insert into message_deletion_logs(message_id,author_id,deleted_by,room,body,caption,created_at) values(old.id,old.user_id,auth.uid(),old.room,old.body,old.caption,old.created_at);return old;end;$$;
drop trigger if exists log_deleted_message_trigger on public.messages;
create trigger log_deleted_message_trigger before delete on public.messages for each row execute function public.log_deleted_message();

alter table public.rooms enable row level security; alter table public.bulletins enable row level security;
alter table public.top_friends enable row level security; alter table public.moderation_actions enable row level security;
alter table public.message_deletion_logs enable row level security;
drop policy if exists "rooms_read" on public.rooms;
drop policy if exists "rooms_create" on public.rooms;
drop policy if exists "rooms_owner_update" on public.rooms;
drop policy if exists "bulletins_read" on public.bulletins;
drop policy if exists "bulletins_write" on public.bulletins;
drop policy if exists "bulletins_delete" on public.bulletins;
drop policy if exists "top_friends_read" on public.top_friends;
drop policy if exists "top_friends_write" on public.top_friends;
drop policy if exists "actions_staff_read" on public.moderation_actions;
drop policy if exists "actions_staff_write" on public.moderation_actions;
drop policy if exists "actions_staff_update" on public.moderation_actions;
drop policy if exists "deletion_logs_staff" on public.message_deletion_logs;
create policy "rooms_read" on public.rooms for select to authenticated using(true);
create policy "rooms_create" on public.rooms for insert to authenticated with check(auth.uid()=owner_id and not is_builtin);
create policy "rooms_owner_update" on public.rooms for update to authenticated using(auth.uid()=owner_id or public.is_moderator()) with check(auth.uid()=owner_id or public.is_moderator());
create policy "bulletins_read" on public.bulletins for select to authenticated using(expires_at is null or expires_at>now());
create policy "bulletins_write" on public.bulletins for insert to authenticated with check(auth.uid()=author_id);
create policy "bulletins_delete" on public.bulletins for delete to authenticated using(auth.uid()=author_id or public.is_moderator());
create policy "top_friends_read" on public.top_friends for select to authenticated using(true);
create policy "top_friends_write" on public.top_friends for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "actions_staff_read" on public.moderation_actions for select to authenticated using(public.is_moderator() or auth.uid()=target_user_id);
create policy "actions_staff_write" on public.moderation_actions for insert to authenticated with check(public.is_moderator() and auth.uid()=moderator_id);
create policy "actions_staff_update" on public.moderation_actions for update to authenticated using(public.is_moderator()) with check(public.is_moderator());
create policy "deletion_logs_staff" on public.message_deletion_logs for select to authenticated using(public.is_moderator());

grant select,insert,update on public.rooms to authenticated;
grant select,insert,delete on public.bulletins to authenticated;
grant select,insert,update,delete on public.top_friends to authenticated;
grant select,insert,update on public.moderation_actions to authenticated;
grant select on public.message_deletion_logs to authenticated;
grant usage,select on all sequences in schema public to authenticated;

-- One authoritative cooldown calculation for official and custom rooms.
create or replace function public.my_room_cooldown_remaining(check_room text)
returns integer language sql stable security definer set search_path=public as $$
  with settings as (select slow_mode_seconds seconds from rooms where slug=check_room),
  latest as (select max(created_at) sent_at from messages where user_id=auth.uid() and room=check_room)
  select case when public.is_moderator(auth.uid()) or coalesce(settings.seconds,0)=0 or latest.sent_at is null then 0
    else greatest(0,ceil(extract(epoch from(latest.sent_at+make_interval(secs=>settings.seconds)-now())))::integer) end
  from settings cross join latest;
$$;
grant execute on function public.my_room_cooldown_remaining(text) to authenticated;

do $$ begin
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='rooms') then alter publication supabase_realtime add table public.rooms; end if;
  if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='bulletins') then alter publication supabase_realtime add table public.bulletins; end if;
end $$;

